<?php require 'includes/auth.php';require_login();$u=user();$s=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY id DESC");$s->execute([$u['id']]);$orders=$s->fetchAll();?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><link rel=stylesheet href=assets/style.css><title>Akun</title></head><body><main><h1>Halo, <?=e($u['name'])?></h1><p><?=e($u['email'])?></p><h2>Riwayat Pesanan</h2><table><tr><th>Order</th><th>Total</th><th>Status</th><th></th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['order_no'])?></td><td><?=rupiah($o['total'])?></td><td><?=e($o['status'])?></td><td><a href="invoice.php?order=<?=$o['id']?>">Invoice</a></td></tr><?php endforeach;?></table><p><a href=logout.php>Keluar</a></p></main></body></html>
